describe('the websocket message handler', () => {
  describe('dispatch', () => {
    it('rejects an unparseable message and never starts a stream', async () => {
      const h = harness([]);

      await h.send({type: 'nonsense'});

      const {calls} = h.processMessageStream.mock;

      expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
    });

    it('answers a ping with the timestamp it was given', async () => {
      const h = harness([]);

      await h.send({type: 'ping', timestamp: 1234});

      expect(h.frames()).toEqual(['pong 1234']);
    });

    it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before', async () => {
      const store = {
        listFor: jest.fn().mockReturnValue([
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 4,
          },
        ]),
      } as unknown as SessionStore;
      const h = harness([], {}, store);

      await h.send({
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
      });

      expect(store.listFor).toHaveBeenCalledWith('u1', {
        limit: 10,
        before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
      });
      expect(h.sent).toEqual([
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ]);
    });

    it('answers an empty session_list when the store has no listFor, and SERVER_ERROR when listFor throws', async () => {
      const storeWithoutList = {} as SessionStore;
      const hWithoutList = harness([], {}, storeWithoutList);
      await hWithoutList.send({type: 'list_sessions'});

      const storeWithFailure = {
        listFor: jest.fn().mockRejectedValue(new Error('db offline')),
      } as unknown as SessionStore;
      const hWithFailure = harness([], {}, storeWithFailure);
      await hWithFailure.send({type: 'list_sessions'});

      expect({
        unimplemented: hWithoutList.sent,
        failed: hWithFailure.sent.map(f => (f.type === 'error' ? {type: f.type, code: f.code} : f)),
      }).toEqual({
        unimplemented: [{type: 'session_list', sessions: []}],
        failed: [{type: 'error', code: 'SERVER_ERROR'}],
      });
    });
  });
